using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using HabitatIsland;
public static class RaftFeedbackRuntimeChecks {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
 const string Dir="Verification/feedback-20261018-144126";static HabitatGame g;static List<string> log=new List<string>();
 static object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,F).Invoke(o,a);
 static async Task Frame(){int f=Time.frameCount;while(Time.frameCount==f)await Task.Delay(8);}
 static async Task Wait(){float end=Time.realtimeSinceStartup+12;do{await Frame();if(Time.realtimeSinceStartup>end)throw new Exception("arrival timeout");}while(g.Busy);}
 static void C(bool b,string m){log.Add((b?"PASS ":"FAIL ")+m);File.WriteAllLines(Dir+"/runtime.txt",log);if(!b)throw new Exception(m);}
 static async Task Capture(string name){g.Hud.ClosePanelsFromInput();g.View.FocusOverview();for(int i=0;i<12;i++){await Frame();if(g.Hud.ModalOpen)g.Hud.ClosePanelsFromInput();}ScreenCapture.CaptureScreenshot(Path.GetFullPath(Dir+"/"+name+".png"));for(int i=0;i<3;i++)await Frame();}
 static Tile T(int x,int z)=>HabitatRules.TileAt(g.State,x,z);
 static Transform World=>(Transform)typeof(HabitatView).GetField("world",F).GetValue(g.View);
 static void Setup(){g.CancelPendingAction();g.Hud.ClosePanels();g.LoadLevel(1);g.State=new HabitatState{levelIndex=1,width=7,depth=7,tiles=Enumerable.Range(0,49).Select(_=>new Tile{height=1}).ToArray(),playerX=1,playerZ=3,dockX=0,dockZ=0,facingX=1,facingZ=0,carryingAnimal=-1,openingCompleted=true};g.paused=true;g.tool=0;g.tuning.animalMovement=false;for(int x=2;x<=5;x++)T(x,3).height=0;T(2,3).prop=PropKind.Raft;T(2,3).rotation=1;g.View.Initialize(g.State);Call(g,"CaptureRetryPoint");}
 public static async Task<string> Run(){for(int i=0;i<300&&HabitatGame.Instance==null;i++)await Frame();g=HabitatGame.Instance;if(!g)throw new Exception("game not ready");log.Clear();var original=Call(g,"CaptureSnapshot");var undo=(Stack<HabitatState>)typeof(HabitatGame).GetField("history",F).GetValue(g);var oldUndo=undo.ToArray();bool session=g.SessionStarted,pause=g.paused,moving=g.tuning.animalMovement;int tool=g.tool;var sf=typeof(HabitatGame).GetField("SaveSlotDirectoryForTests",BindingFlags.NonPublic|BindingFlags.Static);var save=sf.GetValue(null);sf.SetValue(null,Path.GetFullPath(Dir+"/isolated-saves"));typeof(HabitatGame).GetProperty("SessionStarted").SetValue(g,true);
 try{
 Setup();await Frame();g.Move(1,0);C(g.Busy&&g.State.playerX==1,"boarding does not commit before animation arrival");await Wait();C(g.State.playerX==2&&T(2,3).prop==PropKind.Raft,"boarding reaches bamboo deck");
 int count=g.ActionCount;g.Move(1,0);C(g.Busy&&g.State.playerX==2&&T(2,3).prop==PropKind.Raft,"raft departure keeps logical origin until arrival");for(int i=0;i<4;i++)await Frame();g.CancelPendingAction();await Frame();C(g.State.playerX==2&&T(2,3).prop==PropKind.Raft&&T(3,3).prop==PropKind.None&&g.ActionCount==count,"cancel raft restores passenger and original deck without consuming turn");
 g.Move(1,0);float maxGap=0;while(g.Busy){await Frame();var raft=World.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Raft"&&t.gameObject.activeInHierarchy);if(raft){Vector3 delta=g.View.PlayerWorldPosition-raft.position;delta.y=0;maxGap=Mathf.Max(maxGap,delta.magnitude);}}C(maxGap<.025f,"passenger stays bound to moving bamboo (max XZ gap="+maxGap+")");C(g.State.playerX==3&&T(3,3).prop==PropKind.Raft&&T(2,3).prop==PropKind.None&&g.ActionCount==count+1,"raft arrival commits exactly once");
 g.Undo();await Frame();C(g.State.playerX==2&&T(2,3).prop==PropKind.Raft&&T(3,3).prop==PropKind.None,"undo restores raft and rider together");
 g.Select(3,3);g.ApplyTool();C(g.Busy&&g.State.playerX==2,"E/click can ride along the selected water direction");await Wait();g.Move(-1,0);await Wait();C(g.State.playerX==2&&T(2,3).prop==PropKind.Raft,"runtime return trip restores departure endpoint");g.Move(-1,0);await Wait();C(g.State.playerX==1&&T(2,3).prop==PropKind.Raft,"dismount leaves bamboo ready for another trip");
 var water=(Transform)typeof(HabitatView).GetField("water",F).GetValue(g.View);float waterY=(float)typeof(HabitatView).GetField("waterY",F).GetValue(g.View);C(Mathf.Abs(waterY-.725f)<.0001f&&g.View.PlayerWorldPosition.y>.74f,"sea reference and height-one player feet align");C(World.Find("Raft current direction").childCount>=3,"water current markers show rideable corridor");await Capture("bamboo-water-level");
 var saved=JsonUtility.FromJson<HabitatState>(JsonUtility.ToJson(g.State));HabitatSaveValidation.Validate(saved);C(saved.tiles[3*7+2].prop==PropKind.Raft&&saved.tiles[3*7+2].rotation==1,"JSON roundtrip and save validation preserve bamboo direction");
 T(2,3).prop=PropKind.ClimbBlock;T(2,3).height=1;g.View.Initialize(g.State);await Frame();g.Select(2,3);g.tool=0;count=g.ActionCount;g.ApplyTool();C(!g.Busy&&T(2,3).prop==PropKind.ClimbBlock&&g.State.carryingProp==PropKind.None&&count==g.ActionCount,"E cannot carry or move fixed stairs");g.Pull(-1,0);C(!g.Busy&&T(2,3).prop==PropKind.ClimbBlock,"recovery/pull entry rejects fixed stairs");C(((string)Call(g.Hud,"ContextActionLabel")).Contains("固定台阶"),"fixed stair prompt no longer offers pickup");g.Move(1,0,true);await Wait();C(g.State.playerX==2&&T(2,3).prop==PropKind.ClimbBlock,"real Shift climb still reaches fixed stair");await Capture("fixed-climb-stair");
 foreach(int level in new[]{5,6,7,8,10,4,9}){g.LoadLevel(level);g.paused=true;g.Hud.ClosePanels();for(int i=0;i<5;i++)await Frame();HabitatSaveValidation.Validate(g.State);C(!HabitatRules.IsWater(g.State,g.State.playerX,g.State.playerZ)&&g.View.Harbor.Ready,"map "+level+" has dry spawn and bound harbor");C(g.State.tiles.Count(t=>t.prop==PropKind.Raft)==World.GetComponentsInChildren<Transform>(true).Count(t=>t.name=="Raft"),"map "+level+" renders each authored bamboo exactly once");await Capture("map-"+level);}
 // Actual second-map wind changes travel direction, then arrival uses the same Ride binding.
 g.LoadLevel(6);g.State.playerX=4;g.State.playerZ=8;g.State.carryingProp=PropKind.None;T(3,8).prop=PropKind.Fan;T(3,8).rotation=1;g.View.Initialize(g.State);g.paused=true;g.Step();await Wait();g.Step();await Wait();g.Step();await Wait();C(T(4,8).rotation==1&&g.State.playerX==4,"runtime wind changes second-map bamboo axis without ejecting rider");g.Move(1,0);await Wait();C(g.State.playerX==5&&T(5,8).prop==PropKind.Raft,"second map redirected bamboo traverses east");
 // Raised tide preserves authored bamboo and aligns presentation with height-two land.
 g.LoadLevel(8);g.paused=true;g.State.waterLevel=1;g.State.tideActive=true;g.View.Initialize(g.State);await Frame();C(Mathf.Abs((float)typeof(HabitatView).GetField("waterY",F).GetValue(g.View)-1.425f)<.001f,"high tide sea aligns with second terrain layer");C(g.State.tiles.Count(t=>t.prop==PropKind.Raft)==2,"tide keeps both bamboo transports");await Capture("high-tide-water");
 g.State.waterLevel=0;g.State.tideActive=false;g.View.Initialize(g.State);await Frame();C(g.State.tiles.Count(t=>t.prop==PropKind.Raft)==2,"ebb preserves both rafts");
 g.LoadLevel(5);g.paused=true;g.ReturnToHarbor();await Wait();C(g.State.onHarbor&&g.View.Harbor.Ready,"harbor return works after water rise");var boat=World.GetComponentInChildren<HabitatHarborBoat>();C(boat&&boat.Footwell&&boat.Footwell.position.y>HabitatRules.WaterSurfaceY(g.State.waterLevel),"boat passenger footwell remains above raised water");await Capture("harbor-raised-water");
 return "PASS "+log.Count+" actual-frame raft/water/stair/map checks";
 }finally{g.CancelPendingAction();g.Hud.ClosePanels();Call(g,"RestoreSnapshot",original);undo.Clear();for(int i=oldUndo.Length-1;i>=0;i--)undo.Push(oldUndo[i]);typeof(HabitatGame).GetProperty("SessionStarted").SetValue(g,session);g.paused=pause;g.tool=tool;g.tuning.animalMovement=moving;sf.SetValue(null,save);}
 }
}
